def read_records(path: Path, unknown_label: str) -> list[Record]:
    """Read an export of any of the three systems into :class:`Record` values.

    Dates and amounts are converted by the module for the system that wrote the
    file, so every record comes back in dollars with a real date.  A value that
    cannot be converted raises :class:`LedgerParseError` naming the file.
    """
    source = Path(path)
    module = MODULES_BY_SYSTEM[detect_system(source)]
    records: list[Record] = []
    for index, row in enumerate(module.read_rows(source), start=1):
        try:
            records.append(module.to_record(row, unknown_label))
        except LedgerParseError as exc:
            raise LedgerParseError(f"{source.name} data row {index}: {exc}") from exc
    return records
